import React, { useState } from 'react';
import api from '../api';

// Ce composant affiche le formulaire de connexion.
// Quand la connexion réussit, on appelle "onLogin" pour prévenir le composant parent (App.js)
// que l'utilisateur est maintenant connecté.
function Login({ onLogin }) {
    const [email, setEmail] = useState('');
    const [motDePasse, setMotDePasse] = useState('');
    const [erreur, setErreur] = useState('');

    const handleSubmit = async (e) => {
        e.preventDefault(); // on empêche la page de se recharger

        try {
            const reponse = await api.post('/login', {
                email,
                mot_de_passe: motDePasse
            });

            // Connexion réussie : on transmet l'utilisateur reçu au composant parent
            onLogin(reponse.data);

        } catch (err) {
            // Si le backend renvoie une erreur (401 = mauvais email/mot de passe)
            setErreur('Email ou mot de passe incorrect.');
        }
    };

    return (
        <div className="d-flex justify-content-center align-items-center" style={{ minHeight: '100vh' }}>
            <div className="card p-4 shadow" style={{ width: '350px' }}>
                <h3 className="text-center mb-3">Connexion</h3>
                <p className="text-center text-muted">Application GCT - Signature Électronique</p>

                {erreur && <div className="alert alert-danger">{erreur}</div>}

                <form onSubmit={handleSubmit}>
                    <div className="mb-3">
                        <label className="form-label">Email</label>
                        <input
                            type="email"
                            className="form-control"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            required
                        />
                    </div>
                    <div className="mb-3">
                        <label className="form-label">Mot de passe</label>
                        <input
                            type="password"
                            className="form-control"
                            value={motDePasse}
                            onChange={(e) => setMotDePasse(e.target.value)}
                            required
                        />
                    </div>
                    <button type="submit" className="btn btn-primary w-100">
                        Se connecter
                    </button>
                </form>
            </div>
        </div>
    );
}

export default Login;
